"""Prep-pack HTML for the PDF render. The prep pack's content_md is generated by this package in a
known, small markdown subset (h1 `# `, h2 `## `, bullet `- `, paragraphs), so a purpose-built
converter renders it without pulling in a markdown dependency. Styling is the house palette (indigo
#4F5BD5 on white, with a dark variant); the render pipeline (kestrel.docs.render.render_pdf) sets an
explicitly empty header and footer, so no generator or organization string leaks into the PDF."""

from __future__ import annotations

import html

from kestrel.db.models import PrepPack

_CSS = """
@page { size: A4; margin: 18mm 16mm; }
:root { --ink: #1a1a1a; --accent: #4F5BD5; --muted: #555; --line: #e6e6e6; }
* { box-sizing: border-box; }
body { font-family: -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
       color: var(--ink); font-size: 11.5pt; line-height: 1.45; }
h1 { color: var(--accent); font-size: 20pt; margin: 0 0 4pt; }
h2 { color: var(--accent); font-size: 13pt; margin: 16pt 0 4pt;
     border-bottom: 1px solid var(--line); padding-bottom: 2pt; }
ul { margin: 4pt 0 8pt; padding-left: 18pt; }
li { margin: 2pt 0; }
p { margin: 4pt 0; }
"""


def _md_to_html(md: str) -> str:
    out: list[str] = []
    in_list = False

    def close_list() -> None:
        nonlocal in_list
        if in_list:
            out.append("</ul>")
            in_list = False

    for raw in (md or "").splitlines():
        line = raw.rstrip()
        if not line.strip():
            close_list()
            continue
        if line.startswith("## "):
            close_list()
            out.append(f"<h2>{html.escape(line[3:])}</h2>")
        elif line.startswith("# "):
            close_list()
            out.append(f"<h1>{html.escape(line[2:])}</h1>")
        elif line.startswith("- "):
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append(f"<li>{html.escape(line[2:])}</li>")
        else:
            close_list()
            out.append(f"<p>{html.escape(line)}</p>")
    close_list()
    return "\n".join(out)


def prep_pack_html(row: PrepPack, *, org_name: str | None, role: str | None) -> str:
    body = _md_to_html(row.content_md or "")
    title = html.escape(f"Interview prep: {role or 'Role'}")
    return (
        f"<!doctype html><html><head><meta charset='utf-8'><title>{title}</title>"
        f"<style>{_CSS}</style></head><body>{body}</body></html>"
    )
